bgaOccurrence.sourceBlockText:
Event_SystemFailure: {
  name: 'System Failure',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Place a <MALFUNCTION> in each <COMPUTER> Room.'],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_NoWayOut: {
  name: 'No Way Out',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Place 4 Adults in each non-Reinforced Corridor adjacent to the Landing Zone.'],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_TheQueenAwakens: {
  name: 'The Queen Awakens',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['If the Queen is alive, add all Queen tokens to the bag.'],
  secondaryEffectDesc: ['Place a <NOISE> in each Unexplored Corridor without a <NOISE>.'],
},

Event_ScentOfPrey: {
  name: 'Scent Of Prey',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Resolve each <NOISE> adjacent to a <CHARACTER>.'],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_Panic: {
  name: 'Panic',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Each <CHARACTER> in a Room with an <ANY-INTRUDER> or adjacent to a Corridor with an <ANY-INTRUDER>:',
    'Loses 1 <OXYGEN> or spends <AMMO>.',
  ],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_BreakingIn: {
  name: 'Breaking In',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Discard 1 <SECURE> from each Room.'],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_Hatching: {
  name: 'Hatching',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.'],
  primaryEffectDesc: [
    'Place a Larva in the Nest \u2013 it immediately Attack if any <CHARACTER> is there.',
    'Place 1 Larva in each Unexplored Corridor ajdacent to a <CHARACTER>.',
  ],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_EggProtection: {
  name: 'Egg Protection',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.'],
  primaryEffectDesc: [
    'Place 2 Drones in the Nest \u2013 they immediately Attack if any <CHARACTER> is there.',
    'Place 1 Drone in each Unexplored Corridor in Section C.',
  ],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_LandingZoneExplodes: {
  name: 'Landing Zone Explodes',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Place a <FIRE> and a <MALFUNCTION> in the Landing Zone.'],
  secondaryEffectDesc: ['Place a <NOISE> in each Unexplored Corridor without a <NOISE>.'],
},

Event_Damage: {
  name: 'Damage',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.'],
  primaryEffectDesc: ['Place a <MALFUNCTION> in each Room with a <ANY-INTRUDER>.'],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_LifeSupportFailure: {
  name: 'Life Support Failure',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
