  primaryEffectDesc: ['In each Room with a <FIRE>, spread <FIRE> to all neighboring Rooms in Sections with an <OXYGEN-ON>.'],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_DamagingFire: {
  name: 'Damaging Fire',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Place a <MALFUNCTION> in each Room with a <FIRE>.',
    'In each Room with a <FIRE>, spread <FIRE> through Corridors with the lowest Noise value.',
  ],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_OverwhelmingEnemies: {
  name: 'Overwhelming Enemies',
