  primaryEffectDesc: ['Place 1 Drone in each Corridor with a <NOISE> adjacent to a <CHARACTER>.'],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_ProtectServe: {
  name: 'Protect & Serve',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Place 2 Drones in the Room/Corridor with the Queen \u2013 they do not Attack.',
    'If there is no Queen on the map, add 2 random Drone tokens to the bag.',
  ],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_ReactorOverheating: {
  name: 'Reactor Overheating',
  intrudersEffectDesc: [
    'All <ANY-INTRUDER> in each <CORRIDOR-GRAVE>, <CORRIDOR-HOR> and <CORRIDOR-ACUTE>.',
    'Then, all <ANY-INTRUDER> in every Room move.',
  ],
  primaryEffectDesc: [
    'If a <MALFUNCTION> is in the Cooling System Room or the Reactor Room, Activate the Autodestruction Procedure.',
    'Then, place a <MALFUNCTION> in each of these Rooms.',
  ],
  secondaryEffectDesc: ['Reshuffle the Event deck.'],
},

Event_RiseOfTheMachine: {
  name: 'Rise Of The Machine',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Place a <MALFUNCTION> on the <ROBOT>.',
    'Place a <MALFUNCTION> in a Room with the <ROBOT>.',
    'Each <CHARACTER> in that Room loses 2 <HP>.',
  ],
  secondaryEffectDesc: ['Place a <NOISE> in each Unexplored Corridor without a <NOISE>.'],
},

Event_ShortCircuit: {
  name: 'Short Circuit',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['In Sections with an <OXYGEN-ON>:', 'Place a <FIRE> in each Room with a <MALFUNCTION>.'],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
